import sys; sys.path.insert(0, __file__.rsplit('/',1)[0])
from prove_common import *
R=Run('b-workflows-records')
with sync_playwright() as p:
    b=p.chromium.launch(executable_path=os.environ['RENDER_SHELL']); ctx=b.new_context(viewport={'width':1440,'height':900}, accept_downloads=True); pg=ctx.new_page(); R.attach(pg); E=pg.evaluate
    pg.goto(URL+'?view=payments'); pg.wait_for_timeout(900)
    first=E("()=>document.querySelector('#t-py-r-payments tbody tr th').textContent")
    pg.click('#t-py-r-payments .dd .trigger'); pg.wait_for_timeout(150); pg.click('#t-py-r-payments .dd .opt[data-value="gbp:desc"]'); pg.wait_for_timeout(400)
    g=E("()=>document.querySelector('#t-py-r-payments').__rec.rows.slice(0,8).map(r=>r.gbp)")
    R.check('sort dropdown re-orders records (largest first)', g==sorted(g, reverse=True) and E("()=>document.querySelector('#t-py-r-payments tbody tr th').textContent")!=first)
    pg.click('#t-py-r-payments .pg a[data-page="2"]'); pg.wait_for_timeout(400)
    R.check('pagination moves to page 2, marks it current and keeps focus on it', E("()=>[document.querySelector('#t-py-r-payments .pg [aria-current=page]').textContent, document.activeElement.getAttribute('aria-current'), document.querySelector('#t-py-r-payments .ceo-tools .t-cm-caption').textContent]")==['2','page','9–16 of 96 payments'])
    R.check('previous-page control is enabled on page 2', E("()=>!document.querySelector('#t-py-r-payments .pg .ctrl').disabled"))
    pg.reload(); pg.wait_for_timeout(900)
    R.check('sort and page persist across reload', E("()=>[CEO_APP.state.sort.payments, CEO_APP.state.page.payments]")==['gbp:desc',2])
    pg.click('.ph .btn.primary'); pg.wait_for_timeout(600)
    pid=E("()=>document.querySelector('#ceo-sheet h3').textContent.split(' ')[1]")
    R.check('primary action opens the largest payment awaiting approval in the drawer', E("()=>[document.querySelector('#ceo-sheet').classList.contains('open'), document.getElementById('ceo-root').inert, !!document.activeElement.closest('#ceo-sheet')]")==[True,True,True], pid)
    pg.click('#ceo-sheet .sheet-foot button >> nth=0'); pg.wait_for_timeout(600)
    R.check('approve opens ONE modal (the drawer closes) with the audit note field focused', E("()=>[document.querySelector('#ceo-overlay').classList.contains('open'), document.querySelector('#ceo-sheet').classList.contains('open'), document.activeElement.id]")==[True,False,'t1'])
    pg.click('#ceo-overlay [data-role=confirm]'); pg.wait_for_timeout(300)
    R.check('approving £10m+ without a note is refused with a named error', E("()=>[document.querySelector('#ceo-overlay').classList.contains('open'), document.querySelector('#ceo-overlay .tx-group').classList.contains('is-error'), document.getElementById('t1').getAttribute('aria-invalid')]")==[True,True,'true'])
    pg.fill('#t1','Approved after review with the Group Treasurer.'); pg.wait_for_timeout(100)
    R.check('the textarea counter (its own script) counts the note', E("()=>document.getElementById('t1-count').textContent")=='47/300')
    pg.click('#ceo-overlay [data-role=confirm]'); pg.wait_for_timeout(600)
    r=E("(id)=>[CEO_APP.pay(CEO_DATA.payments.find(p=>p.id===id)), CEO_APP.payAudit(CEO_DATA.payments.find(p=>p.id===id)).length, [...document.querySelectorAll('.toast .msg')].map(t=>t.textContent).join('|')]", pid)
    R.check('approval recorded: status Approved, audit entry appended, toast shown', r[0]=='Approved' and r[1]>=2 and 'Approved '+pid in r[2], r)
    pg.click('.ph .btn.primary'); pg.wait_for_timeout(600); pid2=E("()=>document.querySelector('#ceo-sheet h3').textContent.split(' ')[1]")
    pg.click('#ceo-sheet .sheet-foot button >> nth=1'); pg.wait_for_timeout(600); pg.click('#ceo-overlay [data-role=confirm]'); pg.wait_for_timeout(300)
    R.check('reject without a reason is refused', E("()=>document.querySelector('#ceo-overlay').classList.contains('open')"))
    pg.fill('#t1','Duplicate of an earlier instruction.'); pg.click('#ceo-overlay [data-role=confirm]'); pg.wait_for_timeout(600)
    R.check('rejection recorded', E("(id)=>CEO_APP.pay(CEO_DATA.payments.find(p=>p.id===id))", pid2)=='Rejected')
    pg.reload(); pg.wait_for_timeout(900)
    R.check('workflow state persists across reload', E("(ids)=>ids.map(id=>CEO_APP.pay(CEO_DATA.payments.find(p=>p.id===id)))", [pid,pid2])==['Approved','Rejected'])
    pg.click('#t-py-r-payments a.lnk >> nth=0'); pg.wait_for_timeout(500)
    R.check('a payment row opens its detail drawer with summary and audit timeline', E("()=>[!!document.querySelector('#ceo-sheet .cn-summary'), !!document.querySelector('#ceo-sheet .cn-timeline')]")==[True,True])
    pg.keyboard.press('Escape'); pg.wait_for_timeout(300)
    R.check('Escape closes the drawer and returns focus to the row link', E("()=>[document.querySelector('#ceo-sheet').classList.contains('open'), document.activeElement.classList.contains('lnk')]")==[False,True])
    pg.click('#ftbView button[data-view="cards"]'); pg.wait_for_timeout(400)
    R.check('records switch to the List-items card list', E("()=>document.querySelectorAll('#t-py-r-payments .cn-list-items li').length")==8)
    pg.click('#t-py-r-payments .cn-list-items button.row >> nth=0'); pg.wait_for_timeout(400)
    R.check('a card opens its record', E("()=>document.querySelector('#ceo-sheet').classList.contains('open')")); pg.keyboard.press('Escape'); pg.wait_for_timeout(200)
    pg.click('#ftbView button[data-view="table"]'); pg.wait_for_timeout(300)
    # risk acknowledgement
    pg.click('.sh-body > .sn a.sn-link[data-view="risk"]'); pg.wait_for_timeout(700)
    R.check('risk shows a breach alert and four limits meters', E("()=>[document.querySelectorAll('#alerts-risk .alert').length, document.querySelectorAll('[id^=t-rk-m] .lim').length]")==[1,4])
    pg.click('.ph .btn.primary'); pg.wait_for_timeout(600); xid=E("()=>document.querySelector('#ceo-sheet h3').textContent.split(' ')[0]")
    pg.click('#ceo-sheet .sheet-foot button >> nth=0'); pg.wait_for_timeout(600); pg.fill('#t1','too short'); pg.click('#ceo-overlay [data-role=confirm]'); pg.wait_for_timeout(300)
    R.check('acknowledging a material exception needs a 15-character note', E("()=>[document.querySelector('#ceo-overlay').classList.contains('open'), document.querySelector('#ceo-overlay .tx-help').textContent]")[0])
    pg.fill('#t1','Treasury to cut exposure below the cap by Friday.'); pg.click('#ceo-overlay [data-role=confirm]'); pg.wait_for_timeout(600)
    r=E("(id)=>{const x=CEO_DATA.exceptions.find(e=>e.id===id);return [CEO_APP.exc(x), CEO_APP.excAudit(x).slice(-1)[0].note]}", xid)
    R.check('acknowledgement recorded with its audit note', r[0]=='Acknowledged' and 'Friday' in r[1], r)
    # service request
    pg.click('.sh-body > .sn a.sn-link[data-view="messages"]'); pg.wait_for_timeout(700)
    n0=E("()=>document.querySelector('#t-ms-r-requests').__rec.rows.length")
    pg.click('.ph .btn.primary'); pg.wait_for_timeout(600); pg.fill('#t1','Too short'); pg.click('#ceo-sheet .sheet-foot button >> nth=0'); pg.wait_for_timeout(300)
    R.check('service request under 20 characters is refused', E("()=>document.querySelector('#ceo-sheet').classList.contains('open') && document.querySelector('#ceo-sheet .tx-group').classList.contains('is-error')"))
    pg.click('#ceo-sheet .dd .trigger >> nth=0'); pg.wait_for_timeout(150); pg.click('#ceo-sheet .dd .opt[data-value="New account opening"]'); pg.click('#ceo-sheet .seg button[data-value="Urgent"]')
    pg.fill('#t1','Open a USD operating account for the Singapore subsidiary.'); pg.click('#ceo-sheet .sheet-foot button >> nth=0'); pg.wait_for_timeout(700)
    r=E("()=>[CEO_APP.state.wf.srNew.slice(-1)[0], document.querySelector('#t-ms-r-requests').__rec.rows.length]")
    R.check('service request submitted with type, priority and status, and listed', r[0]['type']=='New account opening' and r[0]['priority']=='Urgent' and r[0]['status']=='Submitted' and r[1]==n0+1, [r[0]['id'], r[1]])
    pg.click('#t-ms-r-inbox a.lnk >> nth=0'); pg.wait_for_timeout(500)
    pg.fill('#t1','Thanks — please send the draft.'); pg.click('#ceo-sheet .sheet-foot button >> nth=0'); pg.wait_for_timeout(500)
    R.check('message reply appended to the thread and the message marked read', E("()=>Object.values(CEO_APP.state.wf.msg).some(m=>m.read&&m.thread.length>=2)"))
    # reports
    pg.click('.sh-body > .sn a.sn-link[data-view="reports"]'); pg.wait_for_timeout(700)
    pg.click('.ph .btn.primary'); pg.wait_for_timeout(600)
    R.check('generate the board pack adds a run to Generated reports', E("()=>document.querySelector('#t-rp-r-history').__rec.rows.length")>=1)
    pg.click('#t-rp-r-history a.lnk >> nth=0'); pg.wait_for_timeout(400)
    with pg.expect_download() as d: pg.click('#ceo-sheet .sheet-foot button >> nth=0')
    R.check('a generated report downloads', d.value.suggested_filename.endswith('.csv'), d.value.suggested_filename); pg.keyboard.press('Escape'); pg.wait_for_timeout(200)
    # data grid
    pg.click('.sh-body > .sn a.sn-link[data-view="accounts"]'); pg.wait_for_timeout(800)
    R.check('Data-grid is fed from CEO_DATA under the shared filters', E("()=>[CEO_GRID_ROWS.length>0, document.querySelector('#dgCount').textContent===CEO_GRID_ROWS.length+' results']")==[True,True])
    pg.click('#tbl th[data-key="amount"] .sort'); pg.wait_for_timeout(200); pg.click('#tbl th[data-key="amount"] .sort'); pg.wait_for_timeout(200)
    v=E("()=>[...document.querySelectorAll('#tbody tr td.num')].map(t=>parseFloat(t.textContent.replace(/[^0-9.\\-−]/g,'').replace('−','-')))")
    R.check('Data-grid header sorts descending', v==sorted(v, reverse=True), v[:3])
    pg.fill('#dgSearch','Tamarind'); pg.keyboard.press('Enter'); pg.wait_for_timeout(300)
    R.check('Data-grid search applies a removable chip', E("()=>document.querySelectorAll('#fbar .fchip').length")==1)
    pg.select_option('#pp','24'); pg.wait_for_timeout(300)
    pg.click('#tbody tr >> nth=0 >> td >> nth=2'); pg.wait_for_timeout(500)
    R.check('a Data-grid row opens the transaction drawer', E("()=>document.querySelector('#ceo-sheet h3').textContent.startsWith('Transaction')")); pg.keyboard.press('Escape'); pg.wait_for_timeout(200)
    pg.click('#ftbDensity button[data-density="compact"]'); pg.wait_for_timeout(300)
    R.check('filter-bar density drives the Data-grid density', E("()=>document.getElementById('dg').getAttribute('data-density')")=='compact')
    # settings
    pg.click('.sh-body > .sn a.sn-link[data-view="settings"]'); pg.wait_for_timeout(600)
    pg.click('label[for="ceo-sw-digest"]'); pg.wait_for_timeout(200)
    R.check('notification switch persists its state', E("()=>CEO_APP.state.prefs.notify.digest")==True)
    pg.click('#t-st-f-display .seg button[data-value="dark"]'); pg.wait_for_timeout(300)
    R.check('settings theme control and app-bar control stay in step', E("()=>[document.documentElement.dataset.theme, document.querySelector('.sh-actions .seg button[aria-pressed=true]').dataset.value]")==['dark','dark'])
    R.save(); b.close()
